select * from (select country, case when age >= 59 then 'high' when age >= 28 then 'mid' else 'low' end as age_bucket, concat_ws(', ', sort_array(collect_set(segment))) as segment_values, avg(credit_limit) as avg_credit_limit from customers group by country, case when age >= 59 then 'high' when age >= 28 then 'mid' else 'low' end) as agg where avg_credit_limit > 15800 order by avg_credit_limit, country, age_bucket limit 20;
